// ─── File: tests/transfer.spec.ts ───
import { test, expect } from '@playwright/test';

test.describe('Transfer', () => {
  test('transfer updates balance', async ({ page }, testInfo) => {
    // Named steps make the report read as a narrative, not a wall of actions.
    await test.step('open transfer page', async () => {
      await page.goto('/transfer');
    });

    await test.step('submit transfer of 50000', async () => {
      await page.getByLabel('From account').selectOption('SAV2001');
      await page.getByLabel('To account').fill('CUR3001');
      await page.getByLabel('Amount').fill('50000');
      await page.getByRole('button', { name: 'Transfer' }).click();
    });

    await test.step('verify new balance', async () => {
      // Attach a custom diagnostic artifact for the report.
      const balanceText = await page.getByTestId('account-balance').innerText();
      await testInfo.attach('balance-at-assertion', {
        body: balanceText, contentType: 'text/plain',
      });
      // On failure, HTML/Allure auto-attach screenshot + video + trace,
      // so a developer sees WHY, not just that it failed.
      await expect(page.getByTestId('account-balance')).toContainText('950,000');
    });
  });
});
